```javascript
/**
 * Smoke Plume Particle System + Gaussian Plume Model Visualization
 * Includes: Hero smoke particles, mini card particles, and interactive plume model
 */

(function () {
    'use strict';

    /* =============================================
       HERO SMOKE PARTICLES
       ============================================= */

    class SmokeParticle {
        constructor(canvasWidth, canvasHeight) {
            this.canvasWidth = canvasWidth;
            this.canvasHeight = canvasHeight;
            this.reset();
        }

        reset() {
            this.x = Math.random() * this.canvasWidth;
            this.y = this.canvasHeight + Math.random() * 50;
            this.size = Math.random() * 3 + 1;
            this.speedX = (Math.random() - 0.3) * 0.8;
            this.speedY = -(Math.random() * 1.5 + 0.5);
            this.opacity = Math.random() * 0.3 + 0.05;
            this.fadeRate = Math.random() * 0.003 + 0.001;
            this.life = 0;
            this.maxLife = Math.random() * 200 + 100;
            this.color = {
                r: 180 + Math.random() * 40,
                g: 180 + Math.random() * 40,
                b: 190 + Math.random() * 30
            };
        }

        update() {
            this.x += this.speedX;
            this.y += this.speedY;
            this.life++;
            this.size += 0.02;

            // Random drift
            this.speedX += (Math.random() - 0.5) * 0.05;

            // Fade out in second half of life
            if (this.life > this.maxLife * 0.5) {
                this.opacity -= this.fadeRate;
            }

            // Reset if dead or offscreen
            if (this.opacity <= 0 || this.y < -50 || this.x < -50 || this.x > this.canvasWidth + 50) {
                this.reset();
            }
        }

        draw(ctx) {
            if (this.opacity <= 0) return;
            ctx.save();
            ctx.globalAlpha = Math.max(0, this.opacity);
            ctx.fillStyle = `rgb(${this.color.r}, ${this.color.g}, ${this.color.b})`;
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        }
    }

    class HeroParticleSystem {
        constructor(canvasId) {
            this.canvas = document.getElementById(canvasId);
            if (!this.canvas) return;

            this.ctx = this.canvas.getContext('2d');
            this.particles = [];
            this.animationId = null;
            this.isRunning = false;
            this.particleCount = 80;

            this.resize();
            this.init();
            this.start();

            window.addEventListener('resize', () => this.resize());
        }

        resize() {
            if (!this.canvas) return;
            const dpr = window.devicePixelRatio || 1;
            const rect = this.canvas.parentElement.getBoundingClientRect();

            this.canvas.width = rect.width * dpr;
            this.canvas.height = rect.height * dpr;
            this.canvas.style.width = rect.width + 'px';
            this.canvas.style.height = rect.height + 'px';
            this.ctx.scale(dpr, dpr);

            this.width = rect.width;
            this.height = rect.height;

            // Reinitialize particles with new dimensions
            this.particles.forEach(p => {
                p.canvasWidth = this.width;
                p.canvasHeight = this.height;
            });
        }

        init() {
            this.particles = [];
            for (let i = 0; i < this.particleCount; i++) {
                const p = new SmokeParticle(this.width, this.height);
                // Scatter initial positions
                p.y = Math.random() * this.height;
                p.life = Math.random() * p.maxLife;
                this.particles.push(p);
            }
        }

        start() {
            if (this.isRunning) return;
            this.isRunning = true;
            this.animate();
        }

        stop() {
            this.isRunning = false;
            if (this.animationId) {
                cancelAnimationFrame(this.animationId);
                this.animationId = null;
            }
        }

        animate() {
            if (!this.isRunning) return;

            this.ctx.clearRect(0, 0, this.width, this.height);

            this.particles.forEach(p => {
                p.update();
                p.draw(this.ctx);
            });

            this.animationId = requestAnimationFrame(() => this.animate());
        }
    }

    /* =============================================
       GAUSSIAN PLUME MODEL VISUALIZATION
       ============================================= */

    class GaussianPlumeModel {
        constructor(canvasId) {
            this.canvas = document.getElementById(canvasId);
            if (!this.canvas) return;

            this.ctx = this.canvas.getContext('2d');
            this.windSpeed = 5; // m/s default
            this.emissionRate = 100; // arbitrary units
            this.stackHeight = 50; // meters
            this.animationId = null;
            this.isRunning = false;
            this.time = 0;
            this.smokeParticles = [];
            this.maxParticles = 500;

            this.resize();
            this.initControls();
            this.start();

            window.addEventListener('resize', () => this.resize());
        }

        resize() {
            if (!this.canvas) return;
            const dpr = window.devicePixelRatio || 1;
            const rect = this.canvas.getBoundingClientRect();

            this.canvas.width = rect.width * dpr;
            this.canvas.height = rect.height * dpr;
            this.ctx.scale(dpr, dpr);

            this.width = rect.width;
            this.height = rect.height;

            // Source position (left side, slightly above center)
            this.sourceX = this.width * 0.08;
            this.sourceY = this.height * 0.45;
        }

        initControls() {
            const buttons = document.querySelectorAll('.plume-btn');
            buttons.forEach(btn => {
                btn.addEventListener('click', () => {
                    buttons.forEach(b => b.classList.remove('active'));
                    btn.classList.add('active');
                    this.windSpeed = parseFloat(btn.dataset.wind);
                    this.smokeParticles = []; // Reset particles on change
                });
            });
        }

        /**
         * Gaussian plume dispersion formula (simplified 2D)
         * sigma_y and sigma_z grow with distance from source
         */
        gaussianConcentration(x, y) {
            if (x <= 0) return 0;

            // Pasquill-Gifford dispersion coefficients (Class D - neutral)
            const sigmaY = 0.08 * x * Math.pow(1 + 0.0001 * x, -0.5);
            const sigmaZ = 0.06 * x * Math.pow(1 + 0.0015 * x, -0.5);

            if (sigmaY === 0 || sigmaZ === 0) return 0;

            const Q = this.emissionRate;
            const U = Math.max(this.windSpeed, 0.5);
            const H = 0; // Effective stack height (simplified - centerline)

            // Gaussian formula (y-component only for 2D visualization)
            const expY = Math.exp(-0.5 * Math.pow((y - H) / sigmaY, 2));
            const C = (Q / (2 * Math.PI * sigmaY * sigmaZ * U)) * expY;

            return C;
        }

        /**
         * Create a smoke particle at the source
         */
        emitParticle() {
            const spreadFactor = Math.max(0.5, 3 / Math.sqrt(this.windSpeed));

            return {
                x: this.sourceX,
                y: this.sourceY + (Math.random() - 0.5) * 8,
                vx: (this.windSpeed * 0.8 + Math.random() * this.windSpeed * 0.4) * 0.5,
                vy: (Math.random() - 0.5) * spreadFactor * 0.5,
                size: Math.random() * 3 + 2,
                growRate: Math.random() * 0.05 + 0.02,
                opacity: Math.random() * 0.5 + 0.3,
                fadeRate: 0.001 + Math.random() * 0.002,
                turbulenceX: 0,
                turbulenceY: 0,
                age: 0,
                color: Math.random() > 0.5 ? 'warm' : 'cool'
            };
        }

        /**
         * Update all particles
         */
        updateParticles() {
            // Emit new particles
            const emitRate = Math.max(1, Math.floor(this.windSpeed * 0.5));
            for (let i = 0; i < emitRate; i++) {
                if (this.smokeParticles.length < this.maxParticles) {
                    this.smokeParticles.push(this.emitParticle());
                }
            }

            // Update existing particles
            this.smokeParticles.forEach(p => {
                // Distance from source determines spread
                const distFromSource = p.x - this.sourceX;
                const spreadIncrease = Math.sqrt(Math.max(0, distFromSource)) * 0.01;

                // Turbulence
                p.turbulenceX = Math.sin(this.time * 0.02 + p.y * 0.1) * 0.3;
                p.turbulenceY = Math.cos(this.time * 0.03 + p.x * 0.05) * (0.3 + spreadIncrease);

                // Update position
                p.x += p.vx + p.turbulenceX;
                p.y += p.vy + p.turbulenceY;

                // Gaussian spread increases with distance
                p.vy += (Math.random() - 0.5) * spreadIncrease * 0.5;

                // Grow and fade
                p.size += p.growRate;
                p.opacity -= p.fadeRate;
                p.age++;

                // Slight upward drift (buoyancy)
                p.vy -= 0.01;
            });

            // Remove dead particles
            this.smokeParticles = this.smokeParticles.filter(
                p => p.opacity > 0 && p.x < this.width + 50 && p.y > -50 && p.y < this.height + 50
            );
        }

        /**
         * Draw the heatmap background showing concentration field
         */
        drawConcentrationField() {
            const gridSize = 6;
            const cols = Math.ceil(this.width / gridSize);
            const rows = Math.ceil(this.height / gridSize);

            for (let col = 0; col < cols; col++) {
                for (let row = 0; row < rows; row++) {
                    const px = col * gridSize;
                    const py = row * gridSize;

                    // Convert pixel coordinates to plume coordinates
                    const plumeX = (px - this.sourceX) * 2; // Scale factor
                    const plumeY = (py - this.sourceY);

                    const concentration = this.gaussianConcentration(plumeX, plumeY);

                    if (concentration > 0.0001) {
                        // Map concentration to color (red/orange for high, blue for low)
                        const intensity = Math.min(1, concentration * 500);
                        const r = Math.floor(255 * Math.pow(intensity, 0.6));
                        const g = Math.floor(120 * Math.pow(intensity, 1.2));
                        const b = Math.floor(50 * intensity);
                        const a = Math.min(0.4, intensity * 0.5);

                        this.ctx.fillStyle = `rgba(${r}, ${g}, ${b}, ${a})`;
                        this.ctx.fillRect(px, py, gridSize, gridSize);
                    }
                }
            }
        }

        /**
         * Draw smoke particles
         */
        drawParticles() {
            this.smokeParticles.forEach(p => {
                if (p.opacity <= 0) return;

                this.ctx.save();
                this.ctx.globalAlpha = Math.max(0, p.opacity);

                // Warm particles are orange/red, cool are gray/white
                if (p.color === 'warm') {
                    const gradient = this.ctx.createRadialGradient(
                        p.x, p.y, 0, p.x, p.y, p.size
                    );
                    gradient.addColorStop(0, 'rgba(255, 160, 80, 0.8)');
                    gradient.addColorStop(0.5, 'rgba(200, 100, 50, 0.3)');
                    gradient.addColorStop(1, 'rgba(150, 80, 40, 0)');
                    this.ctx.fillStyle = gradient;
                } else {
                    const gradient = this.ctx.createRadialGradient(
                        p.x, p.y, 0, p.x, p.y, p.size
                    );
                    gradient.addColorStop(0, 'rgba(200, 200, 210, 0.6)');
                    gradient.addColorStop(0.5, 'rgba(160, 160, 170, 0.2)');
                    gradient.addColorStop(1, 'rgba(130, 130, 140, 0)');
                    this.ctx.fillStyle = gradient;
                }

                this.ctx.beginPath();
                this.ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                this.ctx.fill();
                this.ctx.restore();
            });
        }

        /**
         * Draw fire source
         */
        drawSource() {
            const sx = this.sourceX;
            const sy = this.sourceY;

            // Ground line
            this.ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
            this.ctx.lineWidth = 1;
            this.ctx.beginPath();
            this.ctx.moveTo(0, this.height * 0.85);
            this.ctx.lineTo(this.width, this.height * 0.85);
            this.ctx.stroke();

            // Fire glow
            const glowGrad = this.ctx.createRadialGradient(sx, sy, 0, sx, sy, 40);
            glowGrad.addColorStop(0, 'rgba(255, 100, 0, 0.4)');
            glowGrad.addColorStop(0.5, 'rgba(255, 50, 0, 0.1)');
            glowGrad.addColorStop(1, 'rgba(255, 0, 0, 0)');
            this.ctx.fillStyle = glowGrad;
            this.ctx.beginPath();
            this.ctx.arc(sx, sy, 40, 0, Math.PI * 2);
            this.ctx.fill();

            // Fire icon
            this.ctx.fillStyle = '#ff6600';
            this.ctx.font = '24px serif';
            this.ctx.textAlign = 'center';
            this.ctx.textBaseline = 'middle';
            this.ctx.fillText('🔥', sx, sy);
        }

        /**
         * Draw wind indicator
         */
        drawWindIndicator() {
            const padding = 20;
            const x = this.width - 120;
            const y = padding + 10;

            this.ctx.save();
            this.ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
            this.ctx.font = '12px Inter, sans-serif';
            this.ctx.textAlign = 'left';
            this.ctx.fillText(`Wind: ${this.windSpeed} m/s`, x, y);

            // Arrow
            const arrowY = y + 15;
            const arrowLen = Math.min(80, this.windSpeed * 4 + 20);

            this.ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
            this.ctx.lineWidth = 2;
            this.ctx.beginPath();
            this.ctx.moveTo(x, arrowY);
            this.ctx.lineTo(x + arrowLen, arrowY);
            this.ctx.stroke();

            // Arrowhead
            this.ctx.fillStyle = 'rgba(255, 255, 255, 0.6)';
            this.ctx.beginPath();
            this.ctx.moveTo(x + arrowLen, arrowY);
            this.ctx.lineTo(x + arrowLen - 8, arrowY - 4);
            this.ctx.lineTo(x + arrowLen - 8, arrowY + 4);
            this.ctx.closePath();
            this.ctx.fill();

            // Animated wind lines
            for (let i = 0; i < 3; i++) {
                const lineX = x + ((this.time * this.windSpeed * 0.3 + i * 30) % (arrowLen + 20)) - 10;
                if (lineX >= x - 5 && lineX <= x + arrowLen) {
                    this.ctx.strokeStyle = `rgba(255, 255, 255, ${0.2 + Math.random() * 0.1})`;
                    this.ctx.lineWidth = 1;
                    this.ctx.beginPath();
                    this.ctx.moveTo(lineX, arrowY + 8 + i * 6);
                    this.ctx.lineTo(lineX + 15, arrowY + 8 + i * 6);
                    this.ctx.stroke();
                }
            }

            this.ctx.restore();
        }

        /**
         * Draw color scale legend
         */
        drawLegend() {
            const x = 15;
            const y = 15;
            const w = 15;
            const h = 100;

            // Label
            this.ctx.save();
            this.ctx.fillStyle = 'rgba(255, 255, 255, 0.6)';
            this.ctx.font = '10px Inter, sans-serif';
            this.ctx.textAlign = 'left';
            this.ctx.fillText('PM2.5', x, y);

            // Gradient bar
            const gradient = this.ctx.createLinearGradient(x, y + 8, x, y + 8 + h);
            gradient.addColorStop(0, 'rgba(255, 100, 0, 0.8)');
            gradient.addColorStop(0.3, 'rgba(255, 160, 80, 0.5)');
            gradient.addColorStop(0.6, 'rgba(200, 100, 50, 0.3)');
            gradient.addColorStop(1, 'rgba(50, 50, 80, 0.1)');

            this.ctx.fillStyle = gradient;
            this.ctx.fillRect(x, y + 12, w, h);

            // Border
            this.ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
            this.ctx.lineWidth = 1;
            this.ctx.strokeRect(x, y + 12, w, h);

            // Labels
            this.ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
            this.ctx.font = '9px Inter, sans-serif';
            this.ctx.fillText('High', x + w + 5, y + 20);
            this.ctx.fillText('Low', x + w + 5, y + 8 + h);

            this.ctx.restore();
        }

        /**
         * Draw distance scale
         */
        drawScale() {
            const y = this.height - 20;
            const startX = this.sourceX;

            this.ctx.save();
            this.ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
            this.ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
            this.ctx.font = '9px Inter, sans-serif';
            this.ctx.textAlign = 'center';
            this.ctx.lineWidth = 1;

            // Scale markers
            const distances = [0, 5, 10, 20, 50];
            distances.forEach(d => {
                const x = startX + d * (this.width - startX - 20) / 50;
                if (x < this.width - 10) {
                    this.ctx.beginPath();
                    this.ctx.moveTo(x, y - 5);
                    this.ctx.lineTo(x, y + 5);
                    this.ctx.stroke();
                    this.ctx.fillText(`${d}km`, x, y + 15);
                }
            });

            // Scale line
            this.ctx.beginPath();
            this.ctx.moveTo(startX, y);
            this.ctx.lineTo(this.width - 20, y);
            this.ctx.stroke();

            this.ctx.restore();
        }

        /**
         * Main render loop
         */
        render() {
            // Clear with dark background
            this.ctx.fillStyle = '#0a1628';
            this.ctx.fillRect(0, 0, this.width, this.height);

            // Subtle grid
            this.ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
            this.ctx.lineWidth = 1;
            const gridStep = 40;
            for (let x = 0; x < this.width; x += gridStep) {
                this.ctx.beginPath();
                this.ctx.moveTo(x, 0);
                this.ctx.lineTo(x, this.height);
                this.ctx.stroke();
            }
            for (let y = 0; y < this.height; y += gridStep) {
                this.ctx.beginPath();
                this.ctx.moveTo(0, y);
                this.ctx.lineTo(this.width, y);
                this.ctx.stroke();
            }

            // Draw layers
            this.drawConcentrationField();
            this.updateParticles();
            this.drawParticles();
            this.drawSource();
            this.drawWindIndicator();
            this.drawLegend();
            this.drawScale();

            this.time++;
        }

        start() {
            if (this.isRunning) return;
            this.isRunning = true;
            this.animate();
        }

        stop() {
            this.isRunning = false;
            if (this.animationId) {
                cancelAnimationFrame(this.animationId);
                this.animationId = null;
            }
        }

        animate() {
            if (!this.isRunning) return;
            this.render();
            this.animationId = requestAnimationFrame(() => this.animate());
        }
    }

    /* =============================================
       MINI GLOBE ANIMATION
       ============================================= */

    class MiniGlobe {
        constructor(canvasId) {
            this.canvas = document.getElementById(canvasId);
            if (!this.canvas) return;

            this.ctx = this.canvas.getContext('2d');
            this.width = this.canvas.width;
            this.height = this.canvas.height;
            this.radius = Math.min(this.width, this.height) / 2 - 5;
            this.centerX = this.width / 2;
            this.centerY = this.height / 2;
            this.rotation = 0;
            this.animationId = null;

            this.start();
        }

        drawGlobe() {
            const ctx = this.ctx;
            const cx = this.centerX;
            const cy = this.centerY;
            const r = this.radius;

            ctx.clearRect(0, 0, this.width, this.height);

            // Ocean
            const oceanGrad = ctx.createRadialGradient(cx - r * 0.3, cy - r * 0.3, 0, cx, cy, r);
            oceanGrad.addColorStop(0, '#1a5276');
            oceanGrad.addColorStop(1, '#0e2f44');

            ctx.beginPath();
            ctx.arc(cx, cy, r, 0, Math.PI * 2);
            ctx.fillStyle = oceanGrad;
            ctx.fill();

            // Simple continent shapes (rotating)
            ctx.save();
            ctx.beginPath();
            ctx.arc(cx, cy, r, 0, Math.PI * 2);
            ctx.clip();

            ctx.fillStyle = '#2d6a4f';

            // Draw simplified landmasses
            const landmasses = [
                // North America-ish
                { x: -30, y: -25, w: 35, h: 30 },
                // South America-ish
                { x: -20, y: 10, w: 20, h: 35 },
                // Europe/Africa-ish
                { x: 15, y: -20, w: 20, h: 50 },
                // Asia-ish
                { x: 35, y: -30, w: 40, h: 35 },
                // Australia-ish
                { x: 55, y: 15, w: 18, h: 15 },
            ];

            landmasses.forEach(land => {
                const offsetX = ((land.x + this.rotation) % 180) - 90;
                const scale = Math.cos(offsetX * Math.PI / 180);

                if (scale > 0) {
                    const px = cx + offsetX * r / 90;
                    const py = cy + land.y * r / 60;
                    const pw = land.w * scale * r / 90;
                    const ph = land.h * r / 60;

                    ctx.beginPath();
                    ctx.ellipse(px, py, Math.max(1, pw / 2), Math.max(1, ph / 2), 0, 0, Math.PI * 2);
                    ctx.fill();
                }
            });

            // Fire dots
            const fireDots = [
                { x: -25, y: -15 },  // California
                { x: -15, y: 5 },    // Amazon
                { x: 20, y: -5 },    // Africa
                { x: 50, y: -20 },   // Siberia
                { x: 55, y: 20 },    // Australia
            ];

            fireDots.forEach(dot => {
                const offsetX = ((dot.x + this.rotation) % 180) - 90;
                const scale = Math.cos(offsetX * Math.PI / 180);

                if (scale > 0.1) {
                    const px = cx + offsetX * r / 90;
                    const py = cy + dot.y * r / 60;
                    const flickerSize = 2 + Math.sin(this.rotation * 0.1 + dot.x) * 1;

                    // Glow
                    const glow = ctx.createRadialGradient(px, py, 0, px, py, flickerSize * 3);
                    glow.addColorStop(0, 'rgba(255, 100, 0, 0.6)');
                    glow.addColorStop(1, 'rgba(255, 50, 0, 0)');
                    ctx.fillStyle = glow;
                    ctx.beginPath();
                    ctx.arc(px, py, flickerSize * 3, 0, Math.PI * 2);
                    ctx.fill();

                    // Core
                    ctx.fillStyle = `rgba(255, ${150 + Math.random() * 50}, 0, ${0.7 * scale})`;
                    ctx.beginPath();
                    ctx.arc(px, py, flickerSize, 0, Math.PI * 2);
                    ctx.fill();
                }
            });

            ctx.restore();

            // Globe outline
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.arc(cx, cy, r, 0, Math.PI * 2);
            ctx.stroke();

            // Atmosphere glow
            const atmoGrad = ctx.createRadialGradient(cx, cy, r * 0.9, cx, cy, r * 1.15);
            atmoGrad.addColorStop(0, 'rgba(100, 180, 255, 0)');
            atmoGrad.addColorStop(0.5, 'rgba(100, 180, 255, 0.05)');
            atmoGrad.addColorStop(1, 'rgba(100, 180, 255, 0)');
            ctx.fillStyle = atmoGrad;
            ctx.beginPath();
            ctx.arc(cx, cy, r * 1.15, 0, Math.PI * 2);
            ctx.fill();
        }

        start() {
            const animate = () => {
                this.rotation += 0.3;
                if (this.rotation > 360) this.rotation -= 360;
                this.drawGlobe();
                this.animationId = requestAnimationFrame(animate);
            };
            animate();
        }

        stop() {
            if (this.animationId) {
                cancelAnimationFrame(this.animationId);
            }
        }
    }

    /* =============================================
       CARD FIRE/SMOKE MINI PARTICLES
       ============================================= */

    class MiniParticleSystem {
        constructor(containerId, type) {
            this.container = document.getElementById(containerId);
            if (!this.container) return;

            // Create canvas inside the container
            this.canvas = document.createElement('canvas');
            this.canvas.style.position = 'absolute';
            this.canvas.style.top = '0';
            this.canvas.style.left = '0';
            this.canvas.style.width = '100%';
            this.canvas.style.height = '100%';
            this.canvas.style.pointerEvents = 'none';
            this.container.appendChild(this.canvas);

            this.ctx = this.canvas.getContext('2d');
            this.type = type; // 'fire' or 'smoke'
            this.particles = [];
            this.maxParticles = 30;

            this.resize();
            this.start();

            window.addEventListener('resize', () => this.resize());
        }

        resize() {
            const rect = this.container.getBoundingClientRect();
            const dpr = window.devicePixelRatio || 1;
            this.canvas.width = rect.width * dpr;
            this.canvas.height = rect.height * dpr;
            this.ctx.scale(dpr, dpr);
            this.width = rect.width;
            this.height = rect.height;
        }

        emit() {
            if (this.particles.length >= this.maxParticles) return;

            const isFireType = this.type === 'fire';

            this.particles.push({
                x: this.width * 0.3 + Math.random() * this.width * 0.4,
                y: this.height + 5,
                vx: (Math.random() - 0.5) * (isFireType ? 1.5 : 0.8),
                vy: -(Math.random() * 1.5 + 0.5),
                size: Math.random() * (isFireType ? 4 : 3) + 1,
                opacity: Math.random() * 0.4 + 0.1,
                fadeRate: 0.005 + Math.random() * 0.005,
                color: isFireType
                    ? `rgba(255, ${100 + Math.floor(Math.random() * 100)}, 0, 1)`
                    : `rgba(180, 180, 200, 1)`
            });
        }

        update() {
            this.particles.forEach(p => {
                p.x += p.vx + (Math.random() - 0.5) * 0.3;
                p.y += p.vy;
                p.size += 0.03;
                p.opacity -= p.fadeRate;
            });

            this.particles = this.particles.filter(p => p.opacity > 0 && p.y > -20);
        }

        draw() {
            this.ctx.clearRect(0, 0, this.width, this.height);

            this.particles.forEach(p => {
                if (p.opacity <= 0) return;
                this.ctx.save();
                this.ctx.globalAlpha = Math.max(0, p.opacity);
                this.ctx.fillStyle = p.color;
                this.ctx.beginPath();
                this.ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                this.ctx.fill();
                this.ctx.restore();
            });
        }

        start() {
            const animate = () => {
                if (Math.random() > 0.5) this.emit();
                this.update();
                this.draw();
                requestAnimationFrame(animate);
            };
            animate();
        }
    }

    /* =============================================
       INITIALIZATION
       ============================================= */

    function init() {
        // Hero smoke particles
        const heroSystem = new HeroParticleSystem('plumeCanvas');

        // Mini globe
        const globe = new MiniGlobe('miniGlobe');

        // Gaussian plume model
        const plumeModel = new GaussianPlumeModel('plumeVisualization');

        // Card mini particles
        if (document.getElementById('fireParticles')) {
            new MiniParticleSystem('fireParticles', 'fire');
        }
        if (document.getElementById('smokeParticles')) {
            new MiniParticleSystem('smokeParticles', 'smoke');
        }

        // Pause animations when not visible (performance)
        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.target.id === 'plumeVisualization') {
                    if (entry.isIntersecting) {
                        plumeModel.start();
                    } else {
                        plumeModel.stop();
                    }
                }
                if (entry.target.id === 'plumeCanvas') {
                    if (entry.isIntersecting) {
                        heroSystem.start();
                    } else {
                        heroSystem.stop();
                    }
                }
            });
        }, { threshold: 0.1 });

        if (document.getElementById('plumeVisualization')) {
            observer.observe(document.getElementById('plumeVisualization'));
        }
        if (document.getElementById('plumeCanvas')) {
            observer.observe(document.getElementById('plumeCanvas'));
        }
    }

    // Wait for DOM
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    // Expose classes
    window.PlumeVisualizations = {
        HeroParticleSystem,
        GaussianPlumeModel,
        MiniGlobe,
        MiniParticleSystem
    };

})();
